// === Tab: mySketch ===
let h,w,N,dx;

function setup(){
	h = windowHeight;
	w = .75*h;
	N = 100;
	dx = w/N;
  createCanvas(w,h)
	// noLoop() removed for animationcolorMode(HSL)
	noStroke()
}

function draw(){
	for (let i=0;i<N;i++){
		fill(210,random(30,60),random(20,80)); //random blues
		rect(i*dx,0,dx*1.1,h); //draw the vertical lines
	}

	// create a graphics layer to place the manipulated pixels
	let gr = createGraphics(w,h);
	gr.background(0);
	let pd = pixelDensity();

	// strength of the 'random' and 'noise' pixel manipulation
	let randStrength = 7;
	let noiseStrength = 40;

	loadPixels();
	gr.loadPixels();
	for (let p=0; p<pixels.length; p+=4){
		let x = ((p/4)/pd)%w;
		let y = ~~(((p/4)/pd)/w);

		// calculate an offset x-location of a pixel on the canvas to apply to the graphics layer
		let x2 = x + round(pow((y/h),3)*randStrength/1000*w*(random()-random())) + round(pow(y/h,4)*noiseStrength*w/1000*(noise(x/w*10,y/h*10)-.5));
		// wrap that offset location if it goes left or right off-screen
		if (x2 < 0) x2=x2+w;
		if (x2 >= w) x2=x2-w;
		// calculate the index (p2) of the offset location
		p2 = y*w*pd*4 + x2*pd*4;

		// apply the pixel value of the offset canvas value to the graphics layer
		gr.pixels[p]=pixels[p2];
		gr.pixels[p+1]=pixels[p2+1];
		gr.pixels[p+2]=pixels[p2+2];
	}
	updatePixels();
	gr.updatePixels();
	// put the graphics image onto the canvas (and overwrite the original canvas drawing)
	image(gr,0,0)
}
